 public partial class Dashboard : SoftwareRequestBasePage
 {
  protected void Page_Load(object sender,EventArgs e){long id;if(Int64.TryParse(Request.QueryString["download"],out id)){DataTable t=new SoftwareRequestRepository().Attachment(id,CurrentEmployeeID,CanViewAll());if(t.Rows.Count==0)throw new UnauthorizedAccessException();DataRow r=t.Rows[0];string path=Server.MapPath("~/App_Data/SoftwareRequestAttachments/"+Convert.ToString(r["StoredFileName"]));Response.Clear();Response.ContentType=Convert.ToString(r["ContentType"]);Response.AddHeader("Content-Disposition","attachment; filename=\""+Convert.ToString(r["OriginalFileName"]).Replace("\"","")+"\"");Response.TransmitFile(path);Response.Flush();Response.SuppressContent=true;Context.ApplicationInstance.CompleteRequest();}}
  private static List<Dictionary<string,object>> Rows(DataTable t){var a=new List<Dictionary<string,object>>();foreach(DataRow r in t.Rows){var x=new Dictionary<string,object>();foreach(DataColumn c in t.Columns)x[c.ColumnName]=r[c]==DBNull.Value?null:r[c];a.Add(x);}return a;}
  private static string Json(DataTable t){return new JavaScriptSerializer{MaxJsonLength=Int32.MaxValue}.Serialize(Rows(t));}
  private static string Json(DataSet d){var x=new Dictionary<string,object>();for(int i=0;i<d.Tables.Count;i++)x[i==0?"Table":"Table"+i]=Rows(d.Tables[i]);return new JavaScriptSerializer{MaxJsonLength=Int32.MaxValue}.Serialize(x);}
  private static string Text(DataRow r,params string[] names){foreach(string n in names)if(r.Table.Columns.Contains(n)&&r[n]!=DBNull.Value)return Convert.ToString(r[n]);return "";}
  private static bool CanViewAll(){return new SoftwareRequestRepository().IsTeam(CurrentEmployeeID)||new bllLogin().CheckIfPM(CurrentEmployeeID)>0;}
  private static bool CanApprovePriority(){return new bllLogin().CheckIfPM(CurrentEmployeeID)>0;}
  private static DataRow Profile(){DataTable t=new bllLogin().GetUserInformation(CurrentEmployeeID);if(t==null||t.Rows.Count==0)throw new InvalidOperationException("Employee profile not found.");return t.Rows[0];}
  [WebMethod] public static string GetBootstrap(){DataSet d=new SoftwareRequestRepository().Bootstrap(CurrentEmployeeID);DataTable p=new DataTable("Profile");p.Columns.Add("EmployeeID",typeof(int));p.Columns.Add("EmployeeName");p.Columns.Add("Department");p.Columns.Add("CanViewAll",typeof(bool));p.Columns.Add("CanApprovePriority",typeof(bool));DataRow r=Profile();p.Rows.Add(CurrentEmployeeID,Text(r,"EmployeeName","Name","UserName","FullName"),Text(r,"DepartmentName","Department"),CanViewAll(),CanApprovePriority());d.Tables.Add(p);return Json(d);}
  [WebMethod] public static string GetDashboard(){return Json(new SoftwareRequestRepository().Dashboard(CurrentEmployeeID,CanViewAll()));}
  [WebMethod] public static string GetRequests(string scope,string search,string requester,string department,int applicationId,int moduleId,int developerId,string priority,string status){return Json(new SoftwareRequestRepository().List(CurrentEmployeeID,CanViewAll(),scope,search,requester,department,applicationId,moduleId,developerId,priority,status));}
  [WebMethod] public static string GetTaskOwners(){return Json(new SoftwareRequestRepository().TaskOwners(CurrentEmployeeID,CanViewAll()));}
  [WebMethod] public static string GetDetail(long requestId){return Json(new SoftwareRequestRepository().Detail(requestId,CurrentEmployeeID,CanViewAll()));}
  [WebMethod] public static string GetDeveloperReport(int developerId,string scope){if(!CanViewAll())throw new UnauthorizedAccessException();return Json(new SoftwareRequestRepository().DeveloperReport(developerId,scope));}
  [WebMethod] public static string GetActivityOwners(){return Json(new SoftwareRequestRepository().ActivityOwners());}
  [WebMethod] public static string GetActivities(int developerId,DateTime fromDate,DateTime toDate){return Json(new SoftwareRequestRepository().Activities(CurrentEmployeeID,CanViewAll(),developerId,fromDate,toDate));}
  [WebMethod] public static string GetUtilizationReport(int developerId,DateTime fromDate,DateTime toDate){if(!CanViewAll())throw new UnauthorizedAccessException();return Json(new SoftwareRequestRepository().UtilizationReport(developerId,fromDate,toDate));}
  [WebMethod] public static string PreviewPriorityImpact(long requestId,string newPriority){if(!CanViewAll())throw new UnauthorizedAccessException();return Json(new SoftwareRequestRepository().PreviewPriorityImpact(requestId,newPriority));}
  [WebMethod] public static long RequestPriorityChange(long requestId,string newPriority,string reason,DateTime? revisedEta){if(!new SoftwareRequestRepository().IsTeam(CurrentEmployeeID))throw new UnauthorizedAccessException();if(String.IsNullOrWhiteSpace(reason))throw new ArgumentException("Change reason is required.");return new SoftwareRequestRepository().RequestPriorityChange(requestId,CurrentEmployeeID,newPriority,reason.Trim(),revisedEta);}
  [WebMethod] public static string GetPriorityHistory(long requestId){var repo=new SoftwareRequestRepository();repo.Detail(requestId,CurrentEmployeeID,CanViewAll());return Json(repo.PriorityHistory(requestId));}
  [WebMethod] public static string GetPriorityImpactReport(){if(!CanViewAll())throw new UnauthorizedAccessException();return Json(new SoftwareRequestRepository().PriorityImpactReport());}
  [WebMethod] public static long CreateRequest(int requestTypeId,int applicationId,int moduleId,string title,string description,string justification,string requestedPriority,DateTime? requiredBy,string taskOwnerCodes){if(requestTypeId<1||applicationId<1||String.IsNullOrWhiteSpace(title)||String.IsNullOrWhiteSpace(description)||String.IsNullOrWhiteSpace(justification)||String.IsNullOrWhiteSpace(requestedPriority)||String.IsNullOrWhiteSpace(taskOwnerCodes))throw new ArgumentException("Complete all required fields.");if(taskOwnerCodes.Length>500)throw new ArgumentException("Too many task owners selected.");DataRow p=Profile();var repo=new SoftwareRequestRepository();var v=new Hashtable{{"By",CurrentEmployeeID},{"OwnerCodes",taskOwnerCodes.Trim()},{"ByName",Text(p,"EmployeeName","Name","UserName","FullName")},{"Department",Text(p,"DepartmentName","Department")},{"Type",requestTypeId},{"Application",applicationId},{"Module",moduleId},{"Title",title.Trim()},{"Description",description.Trim()},{"Justification",justification.Trim()},{"Priority",requestedPriority},{"RequiredBy",requiredBy}};long id=repo.Create(v);SendUpdateMail(repo,id,"");return id;}
  [WebMethod] public static bool UploadAttachment(long requestId,string fileName,string contentType,string base64){string ext=Path.GetExtension(fileName??"").ToLowerInvariant();string[] allowed={".pdf",".png",".jpg",".jpeg",".doc",".docx",".xls",".xlsx"};if(Array.IndexOf(allowed,ext)<0)throw new ArgumentException("Unsupported file type.");byte[] bytes=Convert.FromBase64String(base64??"");if(bytes.Length<1||bytes.Length>5242880)throw new ArgumentException("Attachment must not exceed 5 MB.");string stored=Guid.NewGuid().ToString("N")+ext;string folder=HttpContext.Current.Server.MapPath("~/App_Data/SoftwareRequestAttachments");Directory.CreateDirectory(folder);File.WriteAllBytes(Path.Combine(folder,stored),bytes);new SoftwareRequestRepository().AddAttachment(requestId,CurrentEmployeeID,Path.GetFileName(fileName),stored,contentType,bytes.Length);return true;}
  private static string SendUpdateMail(SoftwareRequestRepository repo,long requestId,string testEmail){DataTable t=repo.Notification(requestId);if(t.Rows.Count==0)return "Task update saved successfully.";DataRow r=t.Rows[0];var recipients=new HashSet<string>(StringComparer.OrdinalIgnoreCase);Action<string> add=x=>{if(String.IsNullOrWhiteSpace(x))return;try{recipients.Add(new MailAddress(x.Trim()).Address);}catch{}};if(!String.IsNullOrWhiteSpace(testEmail))add(testEmail);else{add(Convert.ToString(r["RequesterEmail"]));add(Convert.ToString(r["DeveloperEmail"]));string[] codes=Convert.ToString(r["RequestOwnerCode"]).Split(new[]{'/'},StringSplitOptions.RemoveEmptyEntries);foreach(DataRow e in repo.Emails(codes).Rows)add(Convert.ToString(e["OfficialEmailID"]));}if(recipients.Count==0)return "Task update saved; no recipient email found.";try{string viewUrl=HttpContext.Current.Request.Url.Scheme+"://"+HttpContext.Current.Request.Url.Authority+VirtualPathUtility.ToAbsolute("~/SoftwareRequests/Dashboard.aspx?id="+requestId);string expected=r["ExpectedCompletionDate"]==DBNull.Value?"":Convert.ToDateTime(r["ExpectedCompletionDate"]).ToString("dd-MMM-yyyy");string cell="padding:7px 10px;border:1px solid #cbd5e1;font-size:12px;line-height:17px";string content="<p style='margin:0 0 14px;font-size:13px;color:#334155'><strong>There is an update on your task.</strong></p><table role='presentation' style='width:100%;border-collapse:collapse;border:1px solid #cbd5e1'><tr><td style='"+cell+"'>Request</td><td style='"+cell+"'>"+HttpUtility.HtmlEncode(Convert.ToString(r["RequestNo"]))+"</td></tr><tr><td style='"+cell+"'>Title</td><td style='"+cell+"'>"+HttpUtility.HtmlEncode(Convert.ToString(r["Title"]))+"</td></tr><tr><td style='"+cell+"'>Status</td><td style='"+cell+"'>"+HttpUtility.HtmlEncode(Convert.ToString(r["StatusCode"]))+"</td></tr><tr><td style='"+cell+"'>Developer</td><td style='"+cell+"'>"+HttpUtility.HtmlEncode(Convert.ToString(r["AssignedDeveloperName"]))+"</td></tr><tr><td style='"+cell+"'>Expected completion</td><td style='"+cell+"'>"+HttpUtility.HtmlEncode(expected)+"</td></tr><tr><td style='"+cell+"'>Latest update</td><td style='"+cell+"'>"+HttpUtility.HtmlEncode(Convert.ToString(r["LatestUpdate"]))+"</td></tr></table><p style='margin:18px 0 0;font-size:12px'><a href='"+HttpUtility.HtmlAttributeEncode(viewUrl)+"' style='display:inline-block;padding:9px 14px;background:#2563eb;color:#fff;text-decoration:none;border-radius:7px;font-weight:700'>Click here to view update</a></p>";using(var mail=new MailMessage()){mail.From=new MailAddress("ack@infinity-data.com","Software Request Tracker",Encoding.UTF8);foreach(string x in recipients)mail.To.Add(x);mail.Subject=Convert.ToString(r["RequestNo"])+" - Task Update";mail.IsBodyHtml=true;mail.Body=SelfLeavesEmailTemplate.Apply(content,"Software task update",true);ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;using(var client=new SmtpClient("smtp.office365.com",587)){client.EnableSsl=true;client.UseDefaultCredentials=false;client.Credentials=new NetworkCredential("ack@infinity-data.com",new bllMaster().GetPassword("ackdata"));client.Send(mail);}}return "Task update saved successfully; email sent.";}catch{return "Task update saved, but email could not be sent.";}}
  private static string SendActivityMail(SoftwareRequestRepository repo,long activityId,string testEmail){DataTable t=repo.ActivityNotification(activityId,CurrentEmployeeID);if(t.Rows.Count==0)return "Activity saved successfully.";DataRow r=t.Rows[0];string recipient=String.IsNullOrWhiteSpace(testEmail)?Convert.ToString(r["OwnerEmail"]):testEmail;try{var valid=new MailAddress(recipient);string viewUrl=HttpContext.Current.Request.Url.Scheme+"://"+HttpContext.Current.Request.Url.Authority+VirtualPathUtility.ToAbsolute("~/SoftwareRequests/Dashboard.aspx?view=activity");string cell="padding:7px 10px;border:1px solid #cbd5e1;font-size:12px";string content="<p><strong>A developer activity has been added for you.</strong></p><table style='width:100%;border-collapse:collapse'><tr><td style='"+cell+"'>Developer</td><td style='"+cell+"'>"+HttpUtility.HtmlEncode(Convert.ToString(r["Developer"]))+"</td></tr><tr><td style='"+cell+"'>Activity</td><td style='"+cell+"'>"+HttpUtility.HtmlEncode(Convert.ToString(r["ActivityType"]))+"</td></tr><tr><td style='"+cell+"'>Description</td><td style='"+cell+"'>"+HttpUtility.HtmlEncode(Convert.ToString(r["Description"]))+"</td></tr><tr><td style='"+cell+"'>Date/Time</td><td style='"+cell+"'>"+Convert.ToDateTime(r["ActivityDate"]).ToString("dd-MMM-yyyy")+" "+r["StartTime"]+" - "+r["EndTime"]+"</td></tr><tr><td style='"+cell+"'>Duration</td><td style='"+cell+"'>"+r["TotalMinutes"]+" minutes</td></tr></table><p><a href='"+HttpUtility.HtmlAttributeEncode(viewUrl)+"' style='display:inline-block;padding:9px 14px;background:#2563eb;color:#fff;text-decoration:none;border-radius:7px;font-weight:700'>Click here to view activity</a></p>";using(var mail=new MailMessage()){mail.From=new MailAddress("ack@infinity-data.com","Software Request Tracker",Encoding.UTF8);mail.To.Add(valid);mail.Subject="Developer Activity - "+Convert.ToString(r["ActivityType"]);mail.IsBodyHtml=true;mail.Body=SelfLeavesEmailTemplate.Apply(content,"Developer activity",true);ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;using(var client=new SmtpClient("smtp.office365.com",587)){client.EnableSsl=true;client.UseDefaultCredentials=false;client.Credentials=new NetworkCredential("ack@infinity-data.com",new bllMaster().GetPassword("ackdata"));client.Send(mail);}}return "Activity saved successfully; email sent.";}catch{return "Activity saved, but email could not be sent.";}}
  [WebMethod] public static string SaveActivity(long activityId,string activityType,string description,int ownerId,string ownerName,DateTime activityDate,string startTime,string endTime,string remarks,string testEmail){var repo=new SoftwareRequestRepository();if(!repo.IsTeam(CurrentEmployeeID))throw new UnauthorizedAccessException("Developer access required.");string[] types={"Meeting","Call/Discussion","Technical Help/Support","Technical Email/Documentation","Investigation/R&D","Other"};if(Array.IndexOf(types,activityType)<0||String.IsNullOrWhiteSpace(description)||ownerId<1)throw new ArgumentException("Complete all required activity fields.");TimeSpan start,end;if(!TimeSpan.TryParse(startTime,out start)||!TimeSpan.TryParse(endTime,out end))throw new ArgumentException("Enter valid start and end times.");long id=repo.SaveActivity(activityId,CurrentEmployeeID,activityType,description.Trim(),ownerId,ownerName,activityDate,start,end,remarks);return activityId==0?SendActivityMail(repo,id,testEmail):"Activity updated successfully.";}
  private static string SendPriorityMail(SoftwareRequestRepository repo,long changeId,string testEmail){DataSet d=repo.PriorityNotification(changeId);if(d.Tables[0].Rows.Count==0)return "Priority approved.";DataRow r=d.Tables[0].Rows[0];var recipients=new HashSet<string>(StringComparer.OrdinalIgnoreCase);if(!String.IsNullOrWhiteSpace(testEmail))recipients.Add(new MailAddress(testEmail).Address);else foreach(DataRow e in d.Tables[1].Rows)try{recipients.Add(new MailAddress(Convert.ToString(e["OfficialEmailID"])).Address);}catch{}if(recipients.Count==0)return "Priority approved; no recipient email found.";try{string impacts="";foreach(DataRow x in d.Tables[2].Rows)impacts+="<tr><td>"+HttpUtility.HtmlEncode(Convert.ToString(x["RequestNo"]))+"</td><td>"+HttpUtility.HtmlEncode(Convert.ToString(x["Title"]))+"</td><td>"+(x["PreviousETA"]==DBNull.Value?"":Convert.ToDateTime(x["PreviousETA"]).ToString("dd-MMM-yyyy"))+"</td><td>"+(x["RevisedETA"]==DBNull.Value?"":Convert.ToDateTime(x["RevisedETA"]).ToString("dd-MMM-yyyy"))+"</td></tr>";string content="<p><strong>Task priority has been changed.</strong></p><p>"+HttpUtility.HtmlEncode(Convert.ToString(r["RequestNo"]))+" - "+HttpUtility.HtmlEncode(Convert.ToString(r["Title"]))+" changed from <strong>"+r["OldPriority"]+"</strong> to <strong>"+r["NewPriority"]+"</strong> by "+HttpUtility.HtmlEncode(Convert.ToString(r["ChangedByName"]))+".</p><p><strong>Reason:</strong> "+HttpUtility.HtmlEncode(Convert.ToString(r["ChangeReason"]))+"</p><p><strong>Previous ETA:</strong> "+(r["PreviousETA"]==DBNull.Value?"":Convert.ToDateTime(r["PreviousETA"]).ToString("dd-MMM-yyyy"))+" &nbsp; <strong>Revised ETA:</strong> "+(r["RevisedETA"]==DBNull.Value?"":Convert.ToDateTime(r["RevisedETA"]).ToString("dd-MMM-yyyy"))+"</p>"+(impacts.Length>0?"<p><strong>Tasks delayed by this reprioritization:</strong></p><table border='1' cellpadding='7' style='border-collapse:collapse'><tr><th>Task</th><th>Title</th><th>Previous ETA</th><th>Revised ETA</th></tr>"+impacts+"</table>":"");using(var mail=new MailMessage()){mail.From=new MailAddress("ack@infinity-data.com","Software Request Tracker",Encoding.UTF8);foreach(string x in recipients)mail.To.Add(x);mail.Subject=Convert.ToString(r["RequestNo"])+" - Priority Changed";mail.IsBodyHtml=true;mail.Body=SelfLeavesEmailTemplate.Apply(content,"Priority change notification",true);ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;using(var client=new SmtpClient("smtp.office365.com",587)){client.EnableSsl=true;client.UseDefaultCredentials=false;client.Credentials=new NetworkCredential("ack@infinity-data.com",new bllMaster().GetPassword("ackdata"));client.Send(mail);}}return "Priority approved; notifications sent.";}catch{return "Priority approved, but notification email could not be sent.";}}
  [WebMethod] public static string ApprovePriorityChange(long requestId,string newPriority,string reason,DateTime? revisedEta,bool managementOverride,string testEmail){if(!CanApprovePriority())throw new UnauthorizedAccessException("Management approval required.");if(String.IsNullOrWhiteSpace(reason))throw new ArgumentException("Change reason is required.");var repo=new SoftwareRequestRepository();long id=repo.ApprovePriorityChange(requestId,CurrentEmployeeID,newPriority,reason.Trim(),revisedEta,managementOverride);return SendPriorityMail(repo,id,testEmail);}
  [WebMethod] public static string UpdateTask(long requestId,int developerId,string developerName,string finalPriority,string status,DateTime? expectedStart,DateTime? expectedCompletion,string latestUpdate,string holdReason,string testEmail){var repo=new SoftwareRequestRepository();if(!repo.IsTeam(CurrentEmployeeID))throw new UnauthorizedAccessException("Software team access required.");bool notify=repo.Update(requestId,CurrentEmployeeID,developerId,developerName,finalPriority,status,expectedStart,expectedCompletion,latestUpdate,holdReason);return notify?SendUpdateMail(repo,requestId,testEmail):"Task updated; status and remarks unchanged.";}
 }
